redesign-orders.translation:
Instrução: Redesenhar a aba de Pedidos do admin com layout profissional, exibindo descrição rica do pedido e dados de conta do cliente (email/senha/backup). Três arquivos: admin/class-admin-page.php, admin/admin.js, assets/style.css.

=== 1. admin/class-admin-page.php — buscar submission por token ===

Localizar o bloco array_map que monta $sessions:
    $sessions = array_map( function( $s ) {
        $uid   = intval( $s['user_id'] );
        $user  = get_userdata( $uid );
        $phone = get_user_meta( $uid, 'billing_phone', true );
        if ( ! $phone ) $phone = get_user_meta( $uid, 'phone', true );
        $s['buyer_name'] = $user ? $user->display_name : 'Usuário #' . $uid;
        $s['phone']      = sanitize_text_field( $phone ?: '' );
        return $s;
    }, $raw_sessions );

Substituir por:
    $sessions = array_map( function( $s ) {
        global $wpdb;
        $uid   = intval( $s['user_id'] );
        $user  = get_userdata( $uid );
        $phone = get_user_meta( $uid, 'billing_phone', true );
        if ( ! $phone ) $phone = get_user_meta( $uid, 'phone', true );
        $s['buyer_name'] = $user ? $user->display_name : 'Usuário #' . $uid;
        $s['phone']      = sanitize_text_field( $phone ?: '' );

        $sub_table  = $wpdb->prefix . 'cs_user_submissions';
        $sub_exists = $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $sub_table ) ) === $sub_table;
        if ( $sub_exists && ! empty( $s['token'] ) ) {
            $sub = $wpdb->get_row(
                $wpdb->prepare(
                    "SELECT email, senha, backup_codes, backup_photo_url, submission_datetime FROM {$sub_table} WHERE token = %s ORDER BY id DESC LIMIT 1",
                    $s['token']
                ),
                ARRAY_A
            );
            $s['submission'] = $sub ?: null;
        } else {
            $s['submission'] = null;
        }
        return $s;
    }, $raw_sessions );

=== 2. admin/admin.js — substituir toda a função initOrders() ===

Localizar o bloco completo:
    function initOrders() {
        var $list = $('#cc-orders-list');
        if (!$list.length) return;
        ...(todo o conteúdo até o } de fechamento antes de $(document).ready)...
    }

Substituir todo esse bloco por:

    function initOrders() {
        var $list = $('#cc-orders-list');
        if (!$list.length) return;

        $list.html('<div class="cc-admin-dme-loading"><span></span><span></span><span></span></div>');

        apiFetch(api + '/packs')
            .then(function (r) { return r.json(); })
            .then(function (res) {
                var packMap = {};
                (res.data || []).forEach(function (p) { packMap[p.id] = p; });
                var sessions = window.ccPacksAdminSessions || [];
                $list.empty();
                if (!sessions.length) {
                    $list.html('<p class="cc-admin-empty">Nenhum pedido encontrado.</p>');
                    return;
                }
                renderOrders(sessions, packMap);
            });

        function esc(str) {
            return String(str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
        }

        function fmtDate(str) {
            if (!str) return '';
            var d = new Date(str.replace(' ', 'T'));
            if (isNaN(d.getTime())) return str;
            return d.toLocaleDateString('pt-BR') + ' às ' + d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
        }

        function renderOrders(sessions, packMap) {
            var statusLabel = { pending: 'Pendente', approved: 'Aprovado', rejected: 'Reprovado' };

            sessions.forEach(function (s) {
                var phone     = (s.phone || '').replace(/\D/g, '');
                var waText    = encodeURIComponent('Olá ' + (s.buyer_name || '') + '! Seu pedido de Packs Chama Coins está pronto.');
                var waHref    = phone ? 'https://wa.me/55' + phone + '?text=' + waText : '';
                var stCls     = 'cc-status-' + (s.status || 'pending');
                var stLabel   = statusLabel[s.status] || (s.status || 'pending');
                var desc      = s.description || Object.keys(s.composition || {}).map(function (pid) {
                    return (packMap[pid] ? packMap[pid].name : 'Pack #' + pid) + ' ×' + s.composition[pid];
                }).join(', ');
                var total     = parseFloat(s.total || 0).toFixed(2).replace('.', ',');
                var sub       = s.submission || null;
                var hasSub    = sub && (sub.email || sub.senha);

                var $card = $('<div class="cc-order-card">');

                // — Header —
                $card.append(
                    '<div class="cc-order-header">' +
                    '  <div class="cc-order-header-left">' +
                    '    <span class="cc-order-buyer">' + esc(s.buyer_name || 'Usuário #' + s.user_id) + '</span>' +
                    (s.created_at ? '<span class="cc-order-date">📅 ' + fmtDate(s.created_at) + '</span>' : '') +
                    '  </div>' +
                    '  <span class="cc-status-badge ' + stCls + '">' + stLabel + '</span>' +
                    '</div>'
                );

                // — Conteúdo do pedido —
                $card.append(
                    '<div class="cc-order-section">' +
                    '  <div class="cc-order-section-title">📦 Conteúdo do pedido</div>' +
                    '  <div class="cc-order-desc">' + esc(desc) + '</div>' +
                    '  <div class="cc-order-total">R$ ' + total + '</div>' +
                    '</div>'
                );

                // — Dados da conta (collapsible) —
                if (hasSub) {
                    var photoHtml = sub.backup_photo_url
                        ? '<div class="cc-order-field"><span class="cc-order-field-label">Foto</span>' +
                          '<a href="' + esc(sub.backup_photo_url) + '" target="_blank"><img src="' + esc(sub.backup_photo_url) + '" class="cc-order-photo-thumb"></a></div>'
                        : '';
                    var backupHtml = sub.backup_codes
                        ? '<div class="cc-order-field"><span class="cc-order-field-label">Backup</span>' +
                          '<span class="cc-order-field-value cc-order-backup-codes">' + esc(sub.backup_codes) + '</span></div>'
                        : '';
                    $card.append(
                        '<div class="cc-order-section cc-order-account-section">' +
                        '  <button type="button" class="cc-order-account-toggle">' +
                        '    <span>🔑 Dados da Conta</span><span class="cc-order-toggle-icon">▼</span>' +
                        '  </button>' +
                        '  <div class="cc-order-account-body" hidden>' +
                        (sub.submission_datetime ? '<div class="cc-order-sub-date">Enviado em: ' + fmtDate(sub.submission_datetime) + '</div>' : '') +
                        '  <div class="cc-order-field"><span class="cc-order-field-label">E-mail</span>' +
                        '    <span class="cc-order-field-value">' + esc(sub.email || '—') + '</span></div>' +
                        '  <div class="cc-order-field"><span class="cc-order-field-label">Senha</span>' +
                        '    <span class="cc-order-field-value cc-order-senha-wrap">' +
                        '      <span class="cc-order-senha-mask" data-val="' + esc(sub.senha || '') + '">••••••••</span>' +
                        '      <button type="button" class="cc-order-toggle-senha">Mostrar</button>' +
                        '    </span></div>' +
                        backupHtml + photoHtml +
                        '  </div>' +
                        '</div>'
                    );
                }

                // — Ações —
                var $actions = $('<div class="cc-order-actions">');
                if (waHref) $actions.append('<a class="cc-admin-btn cc-admin-btn-wa" href="' + waHref + '" target="_blank">💬 WhatsApp</a>');
                $actions.append(
                    '<button class="cc-admin-btn cc-approve-btn" data-id="' + s.id + '">✓ Aprovar</button>' +
                    '<button class="cc-admin-btn cc-admin-btn-danger cc-reject-btn" data-id="' + s.id + '">✕ Reprovar</button>'
                );
                $card.append($actions);
                $list.append($card);
            });

            $list.on('click', '.cc-order-account-toggle', function () {
                var $body = $(this).siblings('.cc-order-account-body');
                var open  = !$body.prop('hidden');
                $body.prop('hidden', open);
                $(this).find('.cc-order-toggle-icon').text(open ? '▼' : '▲');
            });

            $list.on('click', '.cc-order-toggle-senha', function () {
                var $mask    = $(this).siblings('.cc-order-senha-mask');
                var showing  = $(this).data('showing');
                $mask.text(showing ? '••••••••' : $mask.data('val'));
                $(this).text(showing ? 'Mostrar' : 'Ocultar').data('showing', !showing);
            });
        }

        $list.on('click', '.cc-approve-btn', function () {
            apiFetch(api + '/session/' + $(this).data('id') + '/status', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ status: 'approved' }),
            }).then(function () { location.reload(); });
        });
        $list.on('click', '.cc-reject-btn', function () {
            apiFetch(api + '/session/' + $(this).data('id') + '/status', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ status: 'rejected' }),
            }).then(function () { location.reload(); });
        });
    }

=== 3. assets/style.css — adicionar estilos dos cards de pedido ao final ===

Ao final do arquivo, após o último bloco existente, adicionar:

/* ==========================================================
   ADMIN — Cards de Pedido redesenhados
   ========================================================== */

#cc-orders-list {
    display: flex;
    flex-direction: column;
    gap: 16px;
    max-width: 800px;
}

.cc-order-card {
    background: var(--cc-surface);
    border: 1px solid var(--cc-border-mid);
    border-radius: var(--cc-r-md);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    transition: border-color var(--cc-t), box-shadow var(--cc-t);
}
.cc-order-card:hover {
    border-color: var(--cc-border-hi);
    box-shadow: 0 4px 20px rgba(0,0,0,.35);
}

.cc-order-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    padding: 16px 20px 14px;
    background: var(--cc-raised);
    border-bottom: 1px solid var(--cc-border);
}
.cc-order-header-left {
    display: flex;
    flex-direction: column;
    gap: 3px;
}
.cc-order-buyer {
    font-size: 15px;
    font-weight: 700;
    color: var(--cc-text);
    line-height: 1.2;
}
.cc-order-date {
    font-size: 11px;
    color: var(--cc-text-muted);
}

.cc-order-section {
    padding: 14px 20px;
    border-bottom: 1px solid var(--cc-border);
}
.cc-order-section-title {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .8px;
    color: var(--cc-text-muted);
    margin-bottom: 8px;
}
.cc-order-desc {
    font-size: 13px;
    color: var(--cc-text-sub);
    line-height: 1.65;
    margin-bottom: 10px;
    word-break: break-word;
}
.cc-order-total {
    font-size: 20px;
    font-weight: 900;
    color: var(--cc-accent);
    letter-spacing: -.4px;
}

.cc-order-account-section {
    padding: 0;
    border-bottom: 1px solid var(--cc-border);
}
.cc-order-account-toggle {
    width: 100%;
    background: none;
    border: none;
    padding: 13px 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    cursor: pointer;
    color: var(--cc-text-sub);
    font-size: 13px;
    font-weight: 600;
    transition: background var(--cc-t), color var(--cc-t);
    text-align: left;
}
.cc-order-account-toggle:hover {
    background: rgba(255,255,255,.03);
    color: var(--cc-text);
}
.cc-order-toggle-icon {
    font-size: 9px;
    color: var(--cc-text-muted);
    flex-shrink: 0;
}
.cc-order-account-body {
    padding: 6px 20px 16px;
    border-top: 1px solid var(--cc-border);
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.cc-order-sub-date {
    font-size: 11px;
    color: var(--cc-text-muted);
    margin-bottom: 2px;
}
.cc-order-field {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    flex-wrap: wrap;
}
.cc-order-field-label {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .6px;
    color: var(--cc-text-muted);
    min-width: 72px;
    padding-top: 2px;
    flex-shrink: 0;
}
.cc-order-field-value {
    font-size: 13px;
    color: var(--cc-text);
    flex: 1;
    word-break: break-all;
    line-height: 1.5;
}
.cc-order-backup-codes {
    font-family: 'Courier New', monospace;
    font-size: 12px;
    background: var(--cc-bg);
    border: 1px solid var(--cc-border);
    border-radius: var(--cc-r-xs);
    padding: 8px 12px;
    white-space: pre-wrap;
    line-height: 1.7;
    display: block;
    width: 100%;
    color: var(--cc-text-sub);
}
.cc-order-senha-wrap {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}
.cc-order-senha-mask {
    font-family: 'Courier New', monospace;
    font-size: 16px;
    letter-spacing: 3px;
    color: var(--cc-text);
}
.cc-order-toggle-senha {
    background: var(--cc-raised);
    border: 1px solid var(--cc-border);
    color: var(--cc-text-sub);
    border-radius: var(--cc-r-xs);
    padding: 3px 10px;
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    transition: background var(--cc-t), color var(--cc-t), border-color var(--cc-t);
    white-space: nowrap;
}
.cc-order-toggle-senha:hover {
    background: var(--cc-accent);
    color: #000;
    border-color: var(--cc-accent);
}
.cc-order-photo-thumb {
    max-width: 120px;
    max-height: 80px;
    border-radius: var(--cc-r-xs);
    object-fit: cover;
    border: 1px solid var(--cc-border-mid);
    display: block;
    transition: opacity var(--cc-t);
}
.cc-order-photo-thumb:hover { opacity: .8; }

.cc-order-actions {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 14px 20px;
    background: var(--cc-raised);
    flex-wrap: wrap;
}

Verificação: (1) enqueue_assets() busca submission em cs_user_submissions por token e adiciona $s['submission'] com email, senha, backup_codes, backup_photo_url, submission_datetime. (2) initOrders() substituída integralmente: esc(), fmtDate(), renderOrders() com cards .cc-order-card, toggle de conta, toggle de senha, ações. (3) CSS adicionado ao final de assets/style.css cobrindo todos os seletores: .cc-order-card, .cc-order-header, .cc-order-section, .cc-order-account-section, .cc-order-account-toggle, .cc-order-account-body, .cc-order-field, .cc-order-senha-wrap, .cc-order-toggle-senha, .cc-order-photo-thumb, .cc-order-actions.
